const lstDefault = rows.map((x) => x.tk + '|' + x.mk).join('\n'), lstText = st.lst == null ? lstDefault : st.lst;
const onLsave = () => {
  if (st.tab === 'trash') return this.toast('Hãy mở tab khác để thêm hoặc xóa acc');
  const Ls = lstText.split('\n').map((l) => l.trim()).filter(Boolean).map((l) => { const [a, b, c] = l.split('|'); return { tk: (a || '').trim(), mk: (b || '').trim(), p: c !== undefined && c.trim() !== '' && +c >= 0 ? +c : null }; });
  const cur = new Map(rows.filter((x) => !x.del).map((x) => [x.tk, x])), all = new Set(A.map((x) => x.tk)), seen = new Set(), add = [], upd = []; let bad = 0;
  Ls.forEach((o) => { if (!o.tk || !o.mk || seen.has(o.tk)) { bad++; return; } seen.add(o.tk); const x = cur.get(o.tk); if (x) { if (x.mk !== o.mk) upd.push([x, o.mk]); } else if (all.has(o.tk)) bad++; else add.push(o); });
  const gone = [...cur.values()].filter((x) => !seen.has(x.tk));
