  const sub = dsub(); if (add.length && !sub) return this.toast('Hãy tạo thư mục con trước khi thêm acc');
  const base = rows[0] ? rows[0].price : 100000;
  this.ask([add.length && 'Thêm ' + add.length + ' acc vào ' + this.fname(sub) + ' (giá ' + this.fmt(base) + ', có thể ghi tk|mk|giá)', upd.length && 'Đổi mật khẩu ' + upd.length + ' acc', gone.length && 'Xóa ' + gone.length + ' acc (vào thùng rác)', bad && 'Bỏ qua ' + bad + ' dòng lỗi hoặc trùng'].filter(Boolean).join('; ') + '?', () => {
    let id = nextId();
    add.forEach((o) => A.unshift({ id: 'RA-' + (++id), tk: o.tk, mk: o.mk, price: o.p == null ? base : o.p, status: 'Còn hàng', del: false, sub, gift: st.tab === 'gift', img: [] }));
