}, this.pill(x.status), this.acts(x.del ? [['Khôi phục', () => restore(x)], ['Xóa vĩnh viễn', () => purge(x), 1]] : [['Copy', () => this.cpy(x.tk + '|' + x.mk)], ['Sửa', () => accForm(x)], ['Xóa', () => del(x), 1]])));

return Object.assign(this.shell('accounts'), {
